/**********************************************************************/
AFPlasticity::AFPlasticity()  //constructor done
{
    p_maxNewtonIteration = 50;
    p_NewtonError = 1e-6;
    p_verbose = false;

    p_PlasticState = NULL;
    p_elemPlasticState=NULL;

    for (int i = 0; i < 8*6; i++) {
        p_PlasticStrains[i] = NULL;
        p_DeviatoricStresses[i] = NULL;
        p_StressAtk[i] = NULL;
    }


}
