/**********************************************************************/

void AFPlasticity::KdelCPUElemBased(double *x,double *y)
{
    //cout<<"old Kdel"<<endl;
    int freeEncoded,i,j, node2,codedElem,elem,Kindex,maxElem,nodeIndex,ufree,vfree,wfree,row;
    double KP, uResult, vResult, wResult,uVal,vVal,wVal;
    //double p_KPlastic[24*24];
    int k=0;
    //safeFree(KdelTemplates);KdelTemplates = NULL;

    //nTemplateIDs = getNumTemplateIDs();
    #pragma omp parallel for num_threads(8) private( k, freeEncoded,node2,i,j,codedElem,elem,Kindex,maxElem,nodeIndex, ufree,vfree,wfree,KP, uResult,vResult,wResult,uVal,vVal,wVal,row)
    for (int node = 0; node < h_nNodes; node++){
        double p_KPlastic[24*24];

        freeEncoded = h_free[node];
        wfree = freeEncoded >> 2;
        vfree = (freeEncoded - wfree*4)>>1;
        ufree = (freeEncoded - (wfree << 2) -(vfree<<1));
        uResult=0; vResult=0; wResult=0;

        if ((ufree || vfree || wfree)) {// process only if one of the dof  is free
            maxElem = h_nNeighboringElems[node];// how many elements connected to node

            for (j =0; j < maxElem; j++) {//
                codedElem = h_neighborElems[(h_nNodes)*j + node];// process elem-j neighbor
                nodeIndex = codedElem/MAXELEMS;//ranges from 0 to 7, position of this node within this elem
                elem = codedElem - nodeIndex*MAXELEMS;

                row = 24*3*nodeIndex;
                if (!p_elemPlasticState[elem]) continue;

                k=p_elem[elem];
                for (int m=0; m<576; m++)
                p_KPlastic[m]=KPlastic[m+576*k];

                for (i = 0; i < 8; i++) {// now accumulate for each of the 8 nodes
                    node2 = h_elems[(h_nElems)*i + elem];
                    uVal = x[3*node2];
                    vVal = x[3*node2+1];
                    wVal = x[3*node2+2];

                    Kindex = (row + 3*i);
                    KP = p_KPlastic[Kindex];
                    uResult += KP*uVal;

                    Kindex = (row + 3*i+1);
                    KP =  p_KPlastic[Kindex];
                    uResult +=  KP*vVal;

                    Kindex = (row + 3*i+2);
                    KP =  p_KPlastic[Kindex];
                    uResult += KP*wVal;

                    Kindex = (row + 24+3*i);
                    KP =  p_KPlastic[Kindex];
                    vResult += KP*uVal;

                    Kindex = (row + 24+3*i+1);
                    KP =  p_KPlastic[Kindex];
                    vResult += KP*vVal;

                    Kindex = (row + 24+3*i+2);
                    KP =  p_KPlastic[Kindex];
                    vResult += KP*wVal;

                    Kindex = (row + 48+3*i);
                    KP =  p_KPlastic[Kindex];
                    wResult += KP*uVal;

                    Kindex = (row + 48 + 3*i+1);
                    KP =  p_KPlastic[Kindex];
                    wResult += KP*vVal;

                    Kindex = (row + 48 + 3*i+2);
                    KP =  p_KPlastic[Kindex];
                    wResult += KP*wVal;
                }
            }
        }//covers all the nodes
        // write back the result
        y[3*node] = ufree*uResult ;// Dirichlet condition is enforced
        y[3*node+1] = vfree*vResult;
        y[3*node+2] = wfree*wResult;
    }
}
/**********************************************************************/
void AFPlasticity::KPlasticAllPlasticElements(void)
{
    int k=0;

    for (int i=0; i<h_nElems; i++)
        p_elem[i]=0;
    safeFree(KPlastic); if (KPlastic)KPlastic=NULL;
    KPlastic= (double *)malloc(576*numPlasticElems*sizeof(double));
    double Kp[576];
    for (int elem=0; elem< h_nElems; elem++){
        if (p_elemPlasticState[elem]){
            p_elem[elem]=k;
            computeKPlasticMatraixMul(elem,Kp);
            //KPlasticDirectComputation(elem,Kp);
            for (int i=0; i<576; i++)
            KPlastic[i + k*576]=Kp[i];
            k++;
        }
    }
}

/**********************************************************************/
void AFPlasticity::computeKPlasticMatraixMul(int elem, double Kp[576])
{
    //if (p_verbose)	 writeMessageToParetoLog("AFPlasticity: compute KPLastic MatrixMul entered");
    int gp,i,j;
    double pt=1.0/sqrt(3.0);
    double xi[8]= {-pt, pt, pt, -pt, -pt, pt, pt, -pt};
    double eta[8]={-pt, -pt, pt, pt, -pt, -pt, pt, pt};
    double mu[8] = {-pt, -pt, -pt, -pt, pt, pt, pt, pt};
    double gradNxi[8],gradNeta[8],gradNmu[8],T1,T2,T3;
    TCLMatrix J(3,3,0.0);
    double vol = h_dx*h_dy*h_dz;
    double G= p_G;

    J[0][0] = 2./h_dx;//Jinv
    J[1][1] = 2./h_dy;
    J[2][2] = 2./h_dz;

    TCLMatrix B(6,24,0.0);
    TCLMatrix BT(24,6,0.0);
    TCLMatrix KElement(24,24,0.0);
    TCLMatrix D(6,6,0.0);
    double Dmatrix[6][6];
    double dJ=vol/8.0;
    double multipier =2.0*G*dJ;
    int counter=0;

    for (int it = 0; it<576; it++)
        Kp[it]=0;

    for (gp = 0; gp < 8; gp++) {

        if (!p_PlasticState[gp + 8*elem]){
            counter++;
            continue;
        }

        computeGrad_H8(xi[gp],eta[gp],mu[gp],gradNxi,gradNeta,gradNmu);
        // compute D matrix for each gp
        computeDmatrixPlasticity(gp,elem, Dmatrix);
        for (int ii=0; ii<6; ii++)
            for (int jj=0; jj<6; jj++)
                D[ii][jj]=Dmatrix[ii][jj];

        for (i = 0; i < 8; i++) {
            T1 = J[0][0]*gradNxi[i];
            T2 = J[1][1]*gradNeta[i];
            T3 = J[2][2]*gradNmu[i];

            B[0][i] = T1;
            B[1][8+i] = T2;
            B[2][16+i] = T3;
            B[3][i] = T2;
            B[3][8+i] = T1;
            B[4][i] = T3;
            B[4][16+i] = T1;
            B[5][8+i] = T3;
            B[5][16+i] = T2;
        }
        BT = ~B;
        KElement += multipier*BT*D*B;
    }

    if (counter!=8){
        //if (p_verbose)	 writeMessageToParetoLog("AFPlasticity/KPlastic matrix computing for elem = %d", elem);
        int order[24] = {0,8,16,1,9,17,2,10,18,3,11,19,4,12,20,5,13,21,6,14,22,7,15,23};

        int kk=0;
        for (i=0; i <24; i++)
            for (j=0; j <24; j++){
                Kp[kk] = KElement[order[i]][order[j]];
                kk++;
            }
    }
}

