/*bool	AFPlasticity::performTangentialCGWithDeflation(int *niter, double *f)
{
    // Solves Ku = f
    // Assumes K and f have been defined, and Dirichlet conditions have been set
    // Also assumes CG iterations and tolerances have been defined.
    // Solution is returned in h_sol
    if (p_verbose)writeMessageToParetoLog("AFPlastic / Deflation: Performing deflated CG ");

    Timer timer,totalTimer;
    double fractionCompleted,tempDouble;

    //computeKPlasticAllElem();
    CreateDeflationGroups();
    computeSparseWKWPlasticity();

    h_nodeBasedAssembly = false;// only element based

    timer.start();
    totalTimer.start();

    double rho,alpha,beta,rho_new,normr,normr0;
    double *r,*p,*a,*d, *t;

    // use temporary CPU variables
    r = (double *) malloc(3*h_nNodes*sizeof(double));
    p = (double *) malloc(3*h_nNodes*sizeof(double));
    a = (double *) malloc(3*h_nNodes*sizeof(double));
    d = (double *) malloc(3*h_nNodes*sizeof(double));
    t = (double *) malloc(3*h_nNodes*sizeof(double));

    double *temp_force = (double *) malloc(3*h_nNodes*sizeof(double));
    memcpy(temp_force,f,3*h_nNodes*sizeof(double));
    enforceDirichlet0(temp_force);

    safeFree(h_cgNorm);
    h_cgNorm = (double *) malloc(h_CGMaxIter*sizeof(double));

    for (int i=0; i< h_CGMaxIter; i++){
        h_cgNorm[i]=0;
    }

    for (int i=0; i< 3*h_nNodes; i++){
        p_delta_sol[i]=0;   a[i]=0;  r[i]=0; p[i]=0;
    }

    //if (p_verbose) writeMessageToParetoLog("AFPlasticity: Time taken for one Kx: %f (msec) ",timer.getElapsedTimeInMilliSec());
    if (p_verbose) writeMessageToParetoLog("AFPlasticity: normf = %e, norm(sol) =%e ",Norm(temp_force),Norm(p_delta_sol));

    VectorXd mu,result;
    mu.resize(6*ws_nGroups);

    // Performing conjugate gradient here with residual start
    zeaxpy(-1,1,r,a,temp_force);// r =  f; (since solution is 0)
    getWorkSpaceVector(r, mu); // mu = W'*r
    //Compute [W'*K*W]*result = W'*r = mu (from above)
    result = sparseSolver.solve(mu);
    getSolutionSpaceVector(result, t);// t = W*result //this is now the d0 = t

    //enforceDirichlet0(t);
    axpy(1,t,p_delta_sol);

    Ktu(p_delta_sol,a);// a = K*sol
    zeaxpy(-1,1,r,a,temp_force);// r = -a + f
    normr0 = dotprod(r,r);
    normr = 10*normr0;
    //step3 of algo starts below
    //********************************************************
    Ktu(r,t);
    getWorkSpaceVector(t, mu);
    result = sparseSolver.solve(mu);
    getSolutionSpaceVector(result, t);

   // enforceDirichlet0(t);
    zeaxpy(-1,1,p,t,r);// p = r - t
    // step 4 of the algo starts below
    //********************************************
    rho = dotprod(r,r);
    *niter = 1;     // Init counter for number of iterations

    fractionCompleted = 0;
    bool success = true;
    while (normr > h_CGRelativeResErr*normr0)   {
        tempDouble = ((h_CGRelativeResErr*normr0)/normr);
        fractionCompleted = MAX(0,1+0.1*log(tempDouble));// no negative values, at start, fractionCompleted =0 and then converges to 1
        h_cgNorm[*niter-1] = log10(normr/normr0);
        Ktu(p,a);// a = K*p;
        beta = dotprod(a,p);
        alpha = rho/beta;  //Step 5
        axpy(alpha, p,p_delta_sol);//u = u + alpha*p; //Step 6
        if ((*niter)%500 ==0)	{ // restart CG with recomputing residual
            if (p_verbose) writeMessageToParetoLog("Deflation: Restarting CG ");
            Ktu(p_delta_sol,a);// a = K*sol
            zeaxpy(-1,1,r,a,temp_force);// r = -a + f
        }
        else
            axpy(-alpha,a,r);//r = r - alpha*a;// Step 7

        rho_new =  dotprod(r,r);//rho = a'*r
        normr = (rho_new);
        Ktu(r,t);
        getWorkSpaceVector(t, mu);		// mu = W'*t
        result = sparseSolver.solve(mu);
        getSolutionSpaceVector(result, t); // t = W*result
        //enforceDirichlet0(t);
        zeaxpy(1,(rho_new/rho),p,r,p);//p = a + rho_new/rho * p;
        zeaxpy(-1,1,p,t,p);//p = -t + p //Step 10
        rho = rho_new;
        (*niter)++;
        h_nCGItersActual = *niter;

        if (timer.getElapsedTimeInSec() > 120) {//update every 2 mins or so.
            writeMessageToParetoLog("Deflation: Iter: %d	 Rel-err: %.2e ",*niter,normr/normr0);
            timer.stop();
            timer.start();
        }

        if ((p_verbose) && ((*niter)%50 ==0)) writeMessageToParetoLog("Deflation: Iter: %d	 Rel-err: %.2e ",*niter,normr/normr0);
        if (normr >1e3*normr0)  {
            success = false;
            break;
        }

        if (*niter >= ws_DCGMaxIter)  {
            if (p_verbose) writeMessageToParetoLog("Deflation: DCG did not converge in %d iter, resErr = %e ",*niter,normr/normr0);
            success = false;
            break;
        }
    }
    if (p_verbose) writeMessageToParetoLog("Deflation: Norm of solution is = %0.3e\n; relative res = %.3e",Norm(p_delta_sol),normr/normr0);
    if (p_verbose) writeMessageToParetoLog("Deflation: Time taken for iterations = %0.3f (s)",totalTimer.getElapsedTimeInSec());
    if (p_verbose)  writeMessageToParetoLog("Deflation: CG on CPU; nIter = %d, resErr = %e ",*niter,normr/normr0);
    writeMessageToParetoLog("CG: nIter = %d, resErr = %e ",*niter,normr/normr0);
    free(a); a=NULL;
    free(p); p=NULL;
    free(r); r=NULL;
    free(d); d=NULL;
    free(t); t=NULL;
    free(temp_force); temp_force=NULL;
    return success;
}

/**********************************************************************/
void AFPlasticity::computeFInternal(int elem, double fint[24])
{
    //First compute strain components at 1 GP.
    //Secondly compute corresponding stress components at this GP
    //Determine B Matrix at this GP
    //compute B(transpose)sigma at this GP.
    //sum this product for all GPs to get fint for each node
    double sxx, syy, szz, sxy, sxz, syz;
    double Nx, Ny, Nz, gradNxi[8], gradNeta[8], gradNmu[8];
    double pt=1.0/sqrt(3.0);
    double xi[8]= {-pt, pt, pt, -pt, -pt, pt, pt, -pt};
    double eta[8]={-pt, -pt, pt, pt, -pt, -pt, pt, pt};
    double mu[8] = {-pt, -pt, -pt, -pt, pt, pt, pt, pt};
    TCLMatrix J(3,3,0.0);
    double vol = h_dx*h_dy*h_dz;


    J[0][0] = 2.0/h_dx;//Jinv
    J[1][1] = 2.0/h_dy;
    J[2][2] = 2.0/h_dz;

    for (int k=0; k<24; k++)
        fint[k]=0;

    for(int gp = 0; gp < 8; gp++){
        computeGrad_H8(xi[gp], eta[gp], mu[gp], gradNxi, gradNeta, gradNmu);

        //stress at a GP
        sxx=p_StressAtk[0+gp*6][elem];
        syy=p_StressAtk[1+gp*6][elem];
        szz=p_StressAtk[2+gp*6][elem];
        sxy=p_StressAtk[3+gp*6][elem];
        sxz=p_StressAtk[4+gp*6][elem];
        syz=p_StressAtk[5+gp*6][elem];

        for(int i=0; i<8; i++){//contribution from each of the 8 nodes for a given GP
            Nx = J[0][0]*gradNxi[i];
            Ny = J[1][1]*gradNeta[i];
            Nz = J[2][2]*gradNmu[i];

            fint[3*i+0] += (Nx*sxx + Ny*sxy + Nz*sxz)*vol/8.0;
            fint[3*i+1] += (Ny*syy + Nx*sxy + Nz*syz)*vol/8.0;
            fint[3*i+2] += (Nz*szz + Ny*syz + Nx*sxz)*vol/8.0;
        }
    }
}

/**********************************************************************/
bool AFPlasticity::SolveElastoPlasticity(int nSteps)
//bool AFPlasticity::SolveElastoPlasticity(int nSteps, bool (*callBackFunction)(double ))
{
    if (p_verbose)	 writeMessageToParetoLog("AFPlasticity: SolveElastoPlasticity");

    if (p_verbose) writeMessageToParetoLog("AFPlasticity: Solving elasto-plastic");
    int nForceSteps;
    double forceScale,*forceTemp,*forceSave;
    bool NewtonItSuccess;
    reInitializeAllAFPlasticityVariables();
    allocateAFPlasticityMemory();
    initializeSolution();
    nForceSteps = 1;

    forceTemp = (double *)malloc(3*getNumNodes()*sizeof(double));
    forceSave = (double *)malloc(3*getNumNodes()*sizeof(double));
    getForceVector(forceSave);

    for (int forceStep = 1;forceStep <= nForceSteps; forceStep++){
        writeMessageToParetoLog("--------------Force Step: %d------------",forceStep);
        forceScale = forceStep*1.0/nForceSteps;
        copy(forceSave,forceTemp);
        scale(forceScale,forceTemp);
        setForceVector(forceTemp);//update this force value in GPU code variable (h_f)
        NewtonItSuccess = NewtonIteration();
        if (!NewtonItSuccess) {
            if (p_verbose) writeMessageToParetoLog("AFPlasticity: Newton iteration failed");
            free(forceTemp);
            free(forceSave);
            return false;
        }
        if (p_verbose) writeMessageToParetoLog("AFPlasticity: Newton iteration completed");
        setSolutionAtAllNodes(p_sol_temp);
        solveConstitutiveProblemPlasticityPlasticStrainUpdate();

    }
    writeMessageToParetoLog("AFPlasticity: Exiting...");

    setSolutionAtAllNodes(p_sol_temp);
    free(forceTemp);
    free(forceSave);
    return true;
}
